import { llm } from "../llm/index.js";

import type {
  AgentInput,
  AgentExecutionResult,
  VigilAgent,
} from "./agent.types.js";

import type { ExecutionContext } from "../runtime/execution-context.types.js";

export const githubReviewerAgent: VigilAgent = {
  slug: "github-reviewer",
  name: "GitHub Reviewer",

  async execute(
  input: AgentInput,
  context: ExecutionContext
): Promise<AgentExecutionResult> {
    const repository = String(input.repository ?? "");
const pullRequest = Number(input.pullRequest);

if (!repository) {
  throw new Error("repository is required");
}

if (!pullRequest || Number.isNaN(pullRequest)) {
  throw new Error("pullRequest is required");
}

const [owner, repo] = repository.split("/");

if (!owner || !repo) {
  throw new Error(
    "repository must use the format owner/repository"
  );
}

    const pullRequestData =
  await context.tools.github.getPullRequest({
    owner,
    repo,
    pullNumber: pullRequest,
  });

  const changedFiles =
  await context.tools.github.getPullRequestFiles({
    owner,
    repo,
    pullNumber: pullRequest,
  });

    const filesForReview = changedFiles
      .slice(0, 20)
      .map((file) => {
        return `FILE: ${file.filename}
STATUS: ${file.status}
ADDITIONS: ${file.additions}
DELETIONS: ${file.deletions}
PATCH: ${file.patch ?? "Patch unavailable"}`;
      })
      .join("\n---\n");

    const response = await context.llm.generate({
      systemPrompt: `You are a senior software engineer performing rigorous pull request reviews.
You must base your findings only on the supplied pull request metadata and diff.
Do not invent files, bugs, or code that is not present.
Distinguish definite issues from possible concerns.`,
      prompt: `Repository: ${repository}
Pull Request: #${pullRequest}
TITLE: ${pullRequestData.title}
DESCRIPTION: ${pullRequestData.body ?? "No description"}
AUTHOR: ${pullRequestData.author}
BASE: ${pullRequestData.baseBranch}
HEAD: ${pullRequestData.headBranch}
CHANGED FILES:
${filesForReview}

Review the actual diff above.
Return:
1. Summary of the change
2. Bugs or correctness issues
3. Security concerns
4. Maintainability concerns
5. Specific file-level findings
6. Overall recommendation

For every issue, mention the relevant filename.
If you find no meaningful issue, say so explicitly.`,
    });

    return {
      output: {
        review: response.text,
        model: response.model,
        usage: response.usage,
      },
    };
  },
};